import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"رہائش ضمانت کا قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/45-住房保障法.md","filePath":"ur/45-住房保障法.md","lastUpdated":null}'),i={name:"ur/45-住房保障法.md"};function o(e,t,n,h,s,u){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="رہائش-ضمانت-کا-قانون" tabindex="-1">رہائش ضمانت کا قانون <a class="header-anchor" href="#رہائش-ضمانت-کا-قانون" aria-label="Permalink to &quot;رہائش ضمانت کا قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>45</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>رہائش کا حق، ضمانت رہائش، خلائی دائرہ اختیار، رہنے کے قابل ماحول، قیاس آرائی مخالف</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《رہائش ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے پانچ معاون قوانین میں سے ایک ہے، اور اس کا مقصد ہینگیوانژو کے اندر تمام زندگی کے رہائش کے حق کی ضمانت کرنا، منصفانہ، پائیدار رہائش ضمانت کا نظام قائم کرنا، خلائی دائرہ اختیار کی ٹیکنالوجی کا استعمال کرتے ہوئے تمام نسلوں کو مناسب رہائش کی جگہ فراہم کرنا، اور رہائش کے شعبے میں قیاس آرائی اور لوٹ مار کی روک تھام کرنا ہے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>رہائش ضمانت کا اصول</td><td>ہر زندگی کو مناسب رہائش کی جگہ حاصل کرنے کا حق ہے، ریاست اور تہذیب پر بنیادی رہائش کی ضروریات کی ضمانت کرنے کی ذمہ داری ہے</td></tr><tr><td>عوامی بہبود کی ترجیح کا اصول</td><td>رہائش سب سے پہلے زندگی کی بنیادی ضرورت ہے، قیاس آرائی کی چیز نہیں، ضمانت رہائش میں عوامی بہبود کی نوعیت ہے</td></tr><tr><td>خلائی کارکردگی کا اصول</td><td>خلائی دائرہ اختیار کی ٹیکنالوجی کا استعمال کرتے ہوئے جگہ کے استعمال کی کارکردگی کو بڑھانا، رہنے کے قابل جگہ کو وسعت دینا</td></tr><tr><td>دوسری نسلوں کی موافقت کا اصول</td><td>مختلف نسلوں کی جسمانی خصوصیات اور طرز زندگی کی عادات کے مطابق موافق رہائش کی جگہ فراہم کرنا</td></tr><tr><td>رہنے کے قابل ماحول کا اصول</td><td>رہائش کی جگہ میں اچھا ماحولیاتی ماحول، بنیادی بنیادی ڈھانچہ اور عوامی خدمات ہونی چاہئیں</td></tr><tr><td>قیاس آرائی مخالف کا اصول</td><td>رہائش کو مقصد بنا کر قیاس آرائی کرنا ممنوع، رہائش کو دولت لوٹ مار کا آلہ بننے سے روکنا</td></tr></tbody></table><h2 id="ثانياً-رہائش-کے-حق-کی-قانونی-ضمانت" tabindex="-1">ثانياً. رہائش کے حق کی قانونی ضمانت <a class="header-anchor" href="#ثانياً-رہائش-کے-حق-کی-قانونی-ضمانت" aria-label="Permalink to &quot;ثانياً. رہائش کے حق کی قانونی ضمانت&quot;">​</a></h2><p>یہ قانون واضح طور پر مقرر کرتا ہے کہ رہائش کا حق سمبیوسس آئین کے ذریعے ہر زندگی کو عطا کردہ بنیادی حق ہے، اور اس میں مخصوص طور پر شامل ہیں:</p><ol><li><strong>بنیادی رہائش کا حق</strong>: ہر زندگی کو کم از کم معیار سے کم نہ ہونے والی رہائش کی جگہ حاصل کرنے کا حق ہے، اور کم از کم معیار نسل کے جسم کے سائز اور زندگی کی ضروریات کے مطابق طے کیا جاتا ہے۔</li><li><strong>ضمانت رہائش کی درخواست کا حق</strong>: اہل زندگی کو ضمانت رہائش کے لیے درخواست دینے کا حق ہے، اور درخواست کی شرائط اور تقسیم کے معیار کھلے اور شفاف ہیں۔</li><li><strong>رہائش کی حفاظت کا حق</strong>: رہائش کی جگہ کو حفاظتی معیار پر پورا اترنا چاہیے، اور خطرناک گھر اور رہنے کے قابل نہ ہونے والی جگہ کو کرائے پر دینا یا تقسیم کرنا جائز نہیں۔</li><li><strong>رہائش کے استحکام کا حق</strong>: ضمانت رہائش کے رہائشی اہل ہونے کی صورت میں مستحکم رہائش کے حق سے لطف اندوز ہوتے ہیں، اور انہیں من مان طریقے سے نکالا نہیں جا سکتا۔</li><li><strong>رہائش کے ماحول کا حق</strong>: رہائشیوں کو صاف ہوا، پانی کے ذرائع اور اچھے ارد گرد کے ماحول حاصل کرنے کا حق ہے، اور ماحولیاتی آلودگی کے خلاف شکایت کرنے کا حق ہے۔</li><li><strong>رہائش کی ترمیم کا حق</strong>: رہائشیوں کو عمارت کی حفاظت اور دوسروں کے حقوق کو متاثر نہ کرنے کی شرط پر رہائش کی جگہ میں معقول ترمیم کرنے کا حق ہے۔</li></ol><h2 id="ثالثاً-رہائش-ضمانت-کا-نظام" tabindex="-1">ثالثاً. رہائش ضمانت کا نظام <a class="header-anchor" href="#ثالثاً-رہائش-ضمانت-کا-نظام" aria-label="Permalink to &quot;ثالثاً. رہائش ضمانت کا نظام&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے رہائش ضمانت کا نظام تین قسم کی رہائش میں تقسیم ہے، اور مختلف ضروریات کی سطحوں کو کھاتا ہے:</p><table tabindex="0"><thead><tr><th>قسم</th><th>نام</th><th>ضمانت کا مقصد</th><th>تقسیم کا طریقہ</th><th>کرایہ/قیمت</th></tr></thead><tbody><tr><td>پہلی قسم</td><td>عوامی کرایہ رہائش</td><td>کم آمدنی والے گروپ، ابتدائی سادھک، نئے تارکین وطن</td><td>درخواست اور جانچ کا نظام، قطار میں تقسیم</td><td>علامتی کم کرایہ</td></tr><tr><td>دوسری قسم</td><td>مشترکہ ملکیت رہائش</td><td>درمیانی آمدنی والے گروپ، درمیانی سطح کے سادھک</td><td>درخواست اور جانچ کا نظام، لاٹری میں تقسیم</td><td>مارکیٹ قیمت سے کم، فرد اور ریاست کی مشترکہ ملکیت</td></tr><tr><td>تیسری قسم</td><td>تجارتی رہائش</td><td>اعلیٰ آمدنی والے گروپ، اعلیٰ سطح کے سادھک</td><td>مارکیٹ لین دین</td><td>مارکیٹ قیمت، ضابطے کی تابع</td></tr></tbody></table><p>اس کے علاوہ، خلائی جوڑ ٹیکنالوجی کا استعمال کرتے ہوئے &quot;خلائی جوڑ رہائشی علاقہ&quot; تعمیر کیا جاتا ہے: محدود طبعی جگہ کے اندر خلائی جوڑ ٹیکنالوجی کے ذریعے رہائشی رقبہ کو وسعت دینا، اور زیادہ کثافت والے علاقوں میں مزید رہائش کی جگہ فراہم کرنا۔ خلائی جوڑ رہائشی علاقے کو ضرور حفاظتی تشخیص سے گزرنا چاہیے، اور جگہ کے استحکام کو یقینی بنانا چاہیے۔</p><h2 id="رابعاً-دوسری-نسلوں-کی-رہائش-کی-موافقت" tabindex="-1">رابعاً. دوسری نسلوں کی رہائش کی موافقت <a class="header-anchor" href="#رابعاً-دوسری-نسلوں-کی-رہائش-کی-موافقت" aria-label="Permalink to &quot;رابعاً. دوسری نسلوں کی رہائش کی موافقت&quot;">​</a></h2><p>ہینگیوانژو کے اندر مختلف نسلوں کی خصوصی رہائش کی ضروریات کے لیے، یہ قانون دوسری نسلوں کی رہائش کی موافقت کا نظام قائم کرتا ہے:</p><ul><li><strong>آبی نسلیں</strong>: پانی کے نیچے رہائش کی جگہ یا پانی-زمین دونوں طرح کے رہائش فراہم کرنا، پانی کے گردش اور پانی کے معیار کی دیکھ بھال کے نظام سے لیس کرنا۔</li><li><strong>ابھرنے والی نسلیں</strong>: اونچائی پر رہائش کی جگہ یا اتارنا چڑھاؤ پلیٹ فارم والے رہائش فراہم کرنا، فضائی ٹریفک مینجمنٹ سے لیس کرنا۔</li><li><strong>توانائی کی زندگی</strong>: توانائی کی گھنٹہ مناسب رہائش کی جگہ فراہم کرنا، توانائی کے مستحکم آلے سے لیس کرنا۔</li><li><strong>دیوہات نسلیں</strong>: بڑے پیمانے پر رہائش کی جگہ فراہم کرنا، عمارت کے ڈھانچے کو خاص طور پر مضبوط بنانا۔</li><li><strong>خوردبینی نسلیں</strong>: خوردبینی رہائشی علاقہ فراہم کرنا، پیمانہ بدلنے والے چینل اور خصوصی سہولیات سے لیس کرنا۔</li></ul><p>دوسری نسلوں کی رہائش کی موافقت کے معیار رہائش کے محکمہ اور ہر نسل کے نمائندوں کے باہمی تعاون سے طے کیے جاتے ہیں، اور باقاعدگی سے اپ ڈیٹ کیے جاتے ہیں۔</p><h2 id="خامساً-رہائش-کی-تعمیر-اور-انتظام" tabindex="-1">خامساً. رہائش کی تعمیر اور انتظام <a class="header-anchor" href="#خامساً-رہائش-کی-تعمیر-اور-انتظام" aria-label="Permalink to &quot;خامساً. رہائش کی تعمیر اور انتظام&quot;">​</a></h2><ul><li><strong>رہائش کی تعمیر کی منصوبہ بندی</strong>: ریاست آبادی میں اضافے اور تارکین وطن کی صورتحال کے مطابق رہائش کی تعمیر کی منصوبہ بندی تیار کرتی ہے، اور رہائش کی فراہمی اور طلب کے توازن کو یقینی بناتی ہے۔</li><li><strong>تعمیر کے معیار</strong>: ضمانت رہائش کی تعمیر کو ضرور حفاظتی، ماحولیاتی، رہنے کے قابل معیار پر پورا اترنا چاہیے، اور تعمیر کے معیار کو کم کرنا ممنوع ہے۔</li><li><strong>جائیداد کا انتظام</strong>: رہائشی علاقوں میں خود مختار انتظام اور پیشہ ورانہ جائیداد کے انتظام کو یکجا کرنے والا ماڈل نافذ کیا جاتا ہے، اور رہائشیوں کو جائیداد کے انتظام کے فیصلوں میں حصہ لینے کا حق ہے۔</li><li><strong>رہائش کی مرمت</strong>: ضمانت رہائش کی مرمت رہائش کے انتظامی ادارے کی ذمہ داری ہے، اور مرمت کے فنڈز عوامی جمع سے اٹھائے جاتے ہیں۔</li><li><strong>اخراج کا نظام</strong>: جب ضمانت رہائش کے رہائشی کی آمدنی یا سادھنہ کی سطح ضمانت کے معیار سے تجاوز کر جاتی ہے، تو انہیں ضمانت رہائش سے اخراج کرنا یا اسے تجارتی رہائش میں تبدیل کرنا چاہیے، اور اخراج میں معقول عبوری مدت دی جاتی ہے۔</li></ul><h2 id="سادساً-قیاس-آرائی-مخالف-اور-نگرانی" tabindex="-1">سادساً. قیاس آرائی مخالف اور نگرانی <a class="header-anchor" href="#سادساً-قیاس-آرائی-مخالف-اور-نگرانی" aria-label="Permalink to &quot;سادساً. قیاس آرائی مخالف اور نگرانی&quot;">​</a></h2><p>رہائش کے شعبے میں قیاس آرائی اور لوٹ مار کی روک تھام کے لیے، یہ قانون درج ذیل نگرانی کے اقدامات قائم کرتا ہے:</p><ol><li>فرد کے ذریعے تجارتی رہائش رکھنے کی تعداد کو محدود کرنا، اور حد سے تجاوز پر بڑھتی ہوئی پراپرٹی ٹیکس وصول کرنا۔</li><li>ضمانت رہائش کی سب لیز اور دوبارہ فروخت ممنوع، اور خلاف ورزی کرنے والے کی ضمانت کی اہلیت منسوخ اور رہائش واپس لی جائے گی۔</li><li>رہائش کے لین دین کی معلومات کا کھلا نظام قائم کرنا، تاریک باکس آپریشن اور قیمت میں ہیرا پھیری کی روک تھام کرنا۔</li><li>رئیل اسٹیٹ ڈویلپرز کے لیے اہلیت کا انتظام اور فنڈز کی نگرانی نافذ کرنا، نامکمل تعمیر اور دھوکہ دہی کی روک تھام کرنا۔</li><li>رہائش کی شکایات اور تنازعات کے حل کا نظام قائم کرنا، رہائشیوں کے قانونی حقوق کی ضمانت کرنا۔</li></ol><h2 id="سادساً-قانونی-ذمہ-داری" tabindex="-1">سادساً. قانونی ذمہ داری <a class="header-anchor" href="#سادساً-قانونی-ذمہ-داری" aria-label="Permalink to &quot;سادساً. قانونی ذمہ داری&quot;">​</a></h2><p>اس قانون کی دفعات کی خلاف ورزی کرنے والے کارروائیاں جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائیں گی:</p><ul><li>ضمانت رہائش کی خلاف ورزی سے تقسیم کرنے پر، اصلاح کا حکم اور ذمہ دار کو سزا۔</li><li>ضمانت رہائش کی سب لیز، دوبارہ فروخت کرنے پر، ضمانت کی اہلیت منسوخ، رہائش واپس لینا اور جرمانہ۔</li><li>ڈویلپر تعمیر کے معیار کو کم کرنے پر، دوبارہ تعمیر کا حکم اور جرمانہ، سنگین صورتوں میں اہلیت منسوخ۔</li><li>رہائش کی قیاس آرائی کرنے پر، زیادہ قیاس آرائی ٹیکس وصول کرنا اور جرمانہ۔</li><li>خطرناک گھر کرائے پر دے کر رہائشی کو نقصان پہنچانے پر، معاوضے کی ذمہ داری، سنگین صورتوں میں فوجداری ذمہ داری عائد۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《رہائش ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے &quot;ہر ایک کے پاس راستہ ہے&quot; کے تصور کی رہائش کے شعبے میں نفاذ ہے۔ یہ درجہ بندی والا رہائش ضمانت نظام قائم کرنے، خلائی دائرہ اختیار ٹیکنالوجی کا استعمال کرتے ہوئے رہائش کی جگہ کو وسعت دینے، دوسری نسلوں کی رہائش کی ضروریات کی موافقت، رہائش کی قیاس آرائی کو ختم کرنے کے ذریعے، اس بات کو یقینی بناتا ہے کہ ہر زندگی کے پاس ایک محفوظ، مناسب، مستحکم گھر ہو، اور تمام نسلوں کی مشترکہ ترقی کے لیے رہائش کی ضمانت فراہم کرے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>39-住房与环境保障 (رہائش اور ماحول کی ضمانت)</li><li>13-空间法理调度体系详解 (خلائی دائرہ اختیار نظام کی تفصیلی وضاحت)</li><li>46-环境保护法 (ماحولیاتی تحفظ کا قانون)</li></ul>',29)])])}const g=a(i,[["render",o]]);export{c as __pageData,g as default};
